39	const PROCESSING_FEE = 5;
40	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
41	  sword: 100,
42	  amulet: 60,
43	  staff: 80,
44	  potion: 40,
45	  rune: 25,
46	};
47	const FIRST_INSURANCE_RATE = 0.1;
48	
49	const withFirstInsuranceSurcharge = (policyBase: number): number =>
50	  policyBase + policyBase * FIRST_INSURANCE_RATE;
51	
52	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
53	
54	const policyBasePremium = (items: Item[]): number =>
55	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
56	
57	const quotePremium = (items: Item[]): number =>
58	  withFirstInsuranceSurcharge(policyBasePremium(items)) + PROCESSING_FEE;
59	
60	const runStep = (step: Step): StepResult => {
61	  if (step.op === "quote") return { premium: quotePremium(step.items) };
62	  throw new Error(`unsupported step: ${step.op}`);
63	};
64	
65	export const runScenario = (scenario: Scenario): ScenarioResult => ({
66	  results: scenario.steps.map(runStep),
67	});
